const targetPath = path.join(process.cwd(), 'movies.csv');
const existingCsv = fs.readFileSync(targetPath, 'utf8');

const newLines = rawMoviesTsv.trim().split('\n').map(line => {
  const parts = line.split('\t');
  return parts.map(p => `"${(p || '').trim().replace(/"/g, '""')}"`).join(',');
});

let appended = 0;
for (const line of newLines) {
  const titleMatch = line.match(/^"([^"]+)"/);
  const title = titleMatch ? titleMatch[1] : '';
  if (!existingCsv.includes(`"${title}"`)) {
    fs.appendFileSync(targetPath, '\n' + line);
    appended++;
  }
}

console.log(`Successfully appended ${appended} new records from batch to movies.csv.`);
